# -*- coding: utf-8 -*-
import threading
import traceback
import uuid

from elementum.addon import ADDON_PATH
from elementum.dialog_select import DialogSelect
from elementum.logger import log
from elementum.osarch import PLATFORM
from elementum.util import getLocalizedLabel, toUtf8


_lock = threading.RLock()
_pending_open = []
_installed = False


class ProgressiveDialogProxy(object):
    """Thread-safe RPC-side state holder for a progressive Kodi dialog.

    Kodi requires a WindowXMLDialog object to be constructed and entered with
    doModal() from the same long-lived Python thread. The JSON-RPC server uses
    this plain object while the service main thread owns the real DialogSelect.
    """

    def __init__(self, xml_name, title, items):
        self.xml_name = xml_name
        self.title = title
        self.items = list(items)
        self.lock = threading.RLock()
        self.window = None
        self.finished = False
        self.retval = -1
        self.value = ''
        self.session_id = str(uuid.uuid4())
        self.opened = False

    def updateItems(self, items):
        latest = list(items)
        with self.lock:
            self.items = latest
            window = self.window
            finished = self.finished

        log.info(
            'Progressive proxy update: session=%s items=%d window=%s finished=%s'
            % (self.session_id, len(latest), bool(window), finished)
        )

        if window is not None and not finished:
            window.updateItems(latest)

    def result(self):
        with self.lock:
            window = self.window
            result = {
                'done': self.finished,
                'choice': self.retval,
                'value': self.value,
            }

        if window is not None:
            current = window.result()
            with self.lock:
                self.finished = bool(current.get('done', False))
                self.retval = int(current.get('choice', -1))
                self.value = current.get('value', '') or ''
                result = {
                    'done': self.finished,
                    'choice': self.retval,
                    'value': self.value,
                }

        return result

    def close(self):
        with self.lock:
            self.finished = True
            window = self.window

        if window is not None:
            try:
                window.close()
            except Exception as exc:
                log.error(
                    'Progressive proxy close failed: session=%s error=%s'
                    % (self.session_id, repr(exc))
                )

    def hide(self):
        self.close()


def _queue_open(proxy):
    with _lock:
        if proxy not in _pending_open:
            _pending_open.append(proxy)

    log.info(
        'Progressive proxy open queued: session=%s items=%d'
        % (proxy.session_id, len(proxy.items))
    )


def _rpc_progressive_create(server, title, subject, items):
    title_encoded = '%s %s' % (getLocalizedLabel(title), toUtf8(subject))
    xml_name = (
        'DialogSelectLargeLegacy.xml'
        if PLATFORM['kodi'] <= 16
        else 'DialogSelectLarge.xml'
    )

    proxy = ProgressiveDialogProxy(xml_name, title_encoded, items)
    window_id = str(id(proxy))
    server._objects[window_id] = proxy
    _queue_open(proxy)
    return window_id


def _rpc_progressive_update(server, hwnd, items):
    proxy = server._objects.get(hwnd)
    if proxy:
        proxy.updateItems(items)


def _rpc_progressive_result(server, hwnd):
    proxy = server._objects.get(hwnd)
    if not proxy:
        return {'done': True, 'choice': -1}
    return proxy.result()


def _rpc_progressive_close(server, hwnd):
    proxy = server._objects.pop(hwnd, None)
    if proxy:
        proxy.close()


def install_progressive_gui_dispatcher():
    """Replace only the progressive RPC methods with proxy-based versions."""
    global _installed

    with _lock:
        if _installed:
            return

        # Imported here because service.py imports rpc.py before this module is
        # installed. At this point the class is fully defined and safe to patch.
        from elementum.rpc import ElementumRPCServer

        ElementumRPCServer.Dialog_Select_Large_Progressive_Create = (
            _rpc_progressive_create
        )
        ElementumRPCServer.Dialog_Select_Large_Progressive_Update = (
            _rpc_progressive_update
        )
        ElementumRPCServer.Dialog_Select_Large_Progressive_Result = (
            _rpc_progressive_result
        )
        ElementumRPCServer.Dialog_Select_Large_Progressive_Close = (
            _rpc_progressive_close
        )
        _installed = True

    log.info('Progressive GUI main-thread proxy dispatcher installed')


def _sync_proxy_from_window(proxy, window):
    current = window.result()
    with proxy.lock:
        proxy.finished = bool(current.get('done', False))
        proxy.retval = int(current.get('choice', -1))
        proxy.value = current.get('value', '') or ''
        proxy.items = list(window.items)


def _open_proxy(proxy):
    with proxy.lock:
        if proxy.finished or proxy.opened:
            return
        proxy.opened = True
        latest_items = list(proxy.items)

    window = None
    try:
        log.info(
            'Progressive proxy creating DialogSelect on service thread: '
            'session=%s items=%d thread=%s'
            % (
                proxy.session_id,
                len(latest_items),
                threading.current_thread().name,
            )
        )

        # Both construction and doModal() happen in this service MainThread.
        # That is the key difference from the previous black-window attempts.
        window = DialogSelect(
            proxy.xml_name,
            ADDON_PATH,
            'Default',
            title=proxy.title,
            items=latest_items,
        )

        with proxy.lock:
            proxy.window = window
            # A provider update may have arrived during construction.
            newest_items = list(proxy.items)

        if newest_items != latest_items:
            window.updateItems(newest_items)

        if window.web_mode:
            log.info(
                'Progressive proxy attached to Web UI: session=%s items=%d'
                % (proxy.session_id, len(newest_items))
            )
            window.show()
            return

        log.info(
            'Progressive proxy doModal starting: session=%s items=%d thread=%s'
            % (
                proxy.session_id,
                len(newest_items),
                threading.current_thread().name,
            )
        )
        window.doModal()
        _sync_proxy_from_window(proxy, window)
        log.info(
            'Progressive proxy doModal finished: session=%s choice=%d items=%d'
            % (proxy.session_id, proxy.retval, len(proxy.items))
        )
    except Exception as exc:
        with proxy.lock:
            proxy.finished = True
            proxy.retval = -1
            proxy.value = ''
        log.error(
            'Progressive proxy open failed: session=%s error=%s'
            % (proxy.session_id, repr(exc))
        )
        for line in traceback.format_exc().splitlines():
            log.error(line)
    finally:
        # Keep the window reference while Web UI mode is active; its bridge
        # state and later RPC updates depend on that object.
        if window is not None and not window.web_mode:
            with proxy.lock:
                proxy.window = window


def process_pending_progressive_gui():
    # A native doModal() blocks this service-loop iteration until selection,
    # while JSON-RPC/provider processing continues in separate threads.
    with _lock:
        if not _pending_open:
            return
        proxy = _pending_open.pop(0)

    _open_proxy(proxy)
